                               '\n'
                               'class WorkerCrypto extends NodeCryptoProvider {\n'
                               '  async initialize() { initSync(wasm); }\n'
                               '}\n'
                               '\n'
                               'export function clientFactory(input) {\n'
                               '  return new BaseTelegramClient({\n'
                               '    apiId: input.apiId, apiHash: input.apiHash,\n'
                               '    storage: new MemoryStorage(), crypto: new WorkerCrypto(),\n'
                               '    transport: new TcpTransport(), updates: false, disableUpdates: true,\n'
                               '    logLevel: 0,\n'
                               '    platform: {\n'
                               '      beforeExit: () => () => {}, log: () => {}, getDefaultLogLevel: () => '
                               '0,\n'
                               "      getDeviceModel: () => 'Guardian Cloudflare resolver',\n"
                               '    },\n'
                               '    network: { connectionCount: () => 1, usePfs: false },\n'
                               '  });\n'
                               '}\n'
                               '\n'
                               '// No public HTTP API. Only the named service binding can call resolve().\n'
                               "export default { fetch() { return new Response('Not found', { status: 404 "
                               '}); } };\n'
                               'export class ResolverService extends WorkerEntrypoint {\n'
                               '  async resolve(body) {\n'
                               "    if (typeof body !== 'string' || body.length > 2048) return "
                               "JSON.stringify({ error: 'invalid_input' });\n"
                               '    let input;\n'
                               '    try { input = JSON.parse(body); } catch { return JSON.stringify({ error: '
                               "'invalid_input' }); }\n"
                               "    if (!validInput(input)) return JSON.stringify({ error: 'not_configured' "
                               '});\n'
                               "    const stub = this.env.USERS.getByName(input.token.split(':')[0]);\n"
                               "    const result = await stub.fetch('https://resolver.internal/resolve', {\n"
                               "      method: 'POST', headers: { 'Content-Type': 'application/json' }, "
                               'body,\n'
                               '    });\n'
                               '    return result.text();\n'
                               '  }\n'
                               '}\n'
                               '\n'
                               'export class UsernameResolver extends DurableObject {\n'
                               '  busy = false;\n'
                               '  async fetch(request) {\n'
                               "    if (this.busy) return Response.json({ error: 'busy' });\n"
                               '    this.busy = true;\n'
                               '    try {\n'
                               '      const input = await request.json();\n'
                               "      if (!validInput(input)) return Response.json({ error: 'invalid_input' "
