                          '("chat_locks", "expires", now),\n'
                          '                                      ("updates", "started", now-7*86400)]:\n'
                          '            await self.run(f"DELETE FROM {table} WHERE rowid IN (SELECT rowid '
                          'FROM {table} WHERE {column}<? LIMIT 1000)", cutoff)\n'
                          '\n'
                          '\n'
                          'class PersistentCooldowns:\n'
