                           '\n'
                           '\n'
                           'class Statement:\n'
                           '    def __init__(self, conn, sql, args=()):\n'
                           '        self.conn, self.sql, self.args = conn, sql, args\n'
                           '\n'
                           '    def bind(self, *args):\n'
                           '        return Statement(self.conn, self.sql, args)\n'
                           '\n'
                           '    async def first(self):\n'
                           '        row = self.conn.execute(self.sql, self.args).fetchone()\n'
                           '        self.conn.commit()\n'
                           '        return dict(row) if row else None\n'
                           '\n'
                           '    async def run(self):\n'
                           '        cur = self.conn.execute(self.sql, self.args)\n'
                           '        cur.fetchall()\n'
                           '        self.conn.commit()\n'
                           '        return {"success": True, "meta": {"changes": cur.rowcount}}\n'
                           '\n'
                           '    async def all(self):\n'
                           '        rows = self.conn.execute(self.sql, self.args).fetchall()\n'
                           '        self.conn.commit()\n'
                           '        return {"results": [dict(r) for r in rows], "success": True}\n'
                           '\n'
                           '\n'
                           'class Binding:\n'
                           '    def __init__(self):\n'
                           '        self.conn = sqlite3.connect(":memory:")\n'
                           '        self.conn.row_factory = sqlite3.Row\n'
                           '        '
                           'self.conn.executescript((Path(__file__).parents[1]/"schema.sql").read_text())\n'
                           '\n'
                           '    def prepare(self, sql):\n'
                           '        return Statement(self.conn, sql)\n'
                           '\n'
                           '\n'
                           '@pytest.fixture\n'
                           'def db():\n'
                           '    binding = Binding()\n'
                           '    yield Database(binding)\n'
                           '    binding.conn.close()\n'
                           '\n'
                           '\n'
                           'class Telegram:\n'
                           '    def __init__(self):\n'
                           '        self.calls = []\n'
                           '        self.restricted = set()\n'
                           '        self.demoted = set()\n'
