                           '            uid = params["user_id"]\n'
                           '            return {"status": "restricted" if uid in self.restricted else\n'
                           '                    ("administrator" if uid in {1, 999} and uid not in '
                           'self.demoted else "member"),\n'
                           '                    "can_restrict_members": True, "can_delete_messages": True}\n'
                           '        if method == "restrictChatMember" and self.fail_mute:\n'
                           '            raise TelegramAPIError(403)\n'
                           '        return True\n'
                           '\n'
                           '\n'
                           'def update(text="/ping", actor=1, update_id=1, edited=False):\n'
                           '    event = {"message_id": 10, "date": int(time.time()), "chat": {"id": -100123, '
                           '"type": "supergroup"},\n'
