                              "    await run(db,api,f'/mute {uid} 10m',actor=1)\n"
                              "    assert str(uid) in sent(api)[-1]['text']\n"
                              "    assert reason in sent(api)[-1]['text']\n"
                              "    assert not any(m=='restrictChatMember' for m,_ in api.calls)\n"
                              '\n'
                              '\n'
